import React, { useRef, useState } from "react";
import { FilterOutlined } from "@ant-design/icons";
import { Button, Divider, Dropdown, Form, message, Modal, Select, Space, Spin } from "antd";
import { MdArrowDownward, MdArrowUpward } from "react-icons/md";
import { LuArrowUpAZ, LuArrowDownAZ } from "react-icons/lu";
import "../../style/Category.css";
import { FcCheckmark } from "react-icons/fc";
import { FetchbrandList } from "../apiService/api";

function ProductFilter({ setItemType, setFilterBy, setBrandId, onBrandSelect }) {
  const [form] = Form.useForm()
  const [selectedKey, setSelectedKey] = useState(null);
  const [open, setOpen] = useState(false);
  const [selectedBrandId, setSelectedBrandId] = useState("");
  const [selectedBrandName, setSelectedBrandName] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [brandList, setBrandList] = useState([]);
  const [isBrandLoading, setIsBrandLoading] = useState(false);
  const debounceSearch = useRef(null);

  const initialItems = [
    {
      key: "1",
      label: "Price high to low",
      sortby: "bkdAmount",
      sortType: "DESC",
      icon: <MdArrowUpward className="sort_icons" />,
      extra: "⌘P",
    },
    {
      key: "2",
      label: "Price low to high",
      sortby: "bkdAmount",
      sortType: "ASC",
      icon: <MdArrowDownward className="sort_icons" />,
      extra: "⌘B",
    },
    {
      key: "3",
      label: "A to Z",
      sortby: "productName",
      sortType: "ASC",
      icon: <LuArrowUpAZ className="sort_icons" />,
      extra: "⌘S",
    },
    {
      key: "4",
      label: "Z to A",
      sortby: "productName",
      sortType: "DESC",
      icon: <LuArrowDownAZ className="sort_icons" />,
      extra: "⌘S",
    },
    {
      key: "5",
      label: selectedBrandName || "Select Brand",
      sortby: "productName",
      type: "brand",
    }
  ];

  const showAllBrandList = async (search = "") => {
    setIsBrandLoading(true)
    try {
      await FetchbrandList(1, search)
        .then((res) => {
          if (res.status == 200) {
            setBrandList(res.data.data);
            setIsBrandLoading(false)
          }
        })
        .catch((err) => {
          message.error(err)
          setIsBrandLoading(false)
        });
    } catch (error) {
      message.error(error)
      setIsBrandLoading(false)
    }
  };

  const handleFilter = (info) => {
    const { key } = info;
    const selectedItem = initialItems.find((item) => item.key === key); // Find selected item by key

    if (key === "5") {
      setIsModalOpen(true);
      setOpen(false);
      showAllBrandList("")
      return;
    }

    setSelectedKey(key); // Update selected key
    setItemType(selectedItem?.sortType);
    setFilterBy(selectedItem?.sortby);
    setSelectedBrandId("");
    setSelectedBrandName("");
    setOpen(false);
  };

  const submitHandler = () => {
    if (!selectedBrandId) {
      message.error("Please select brand");
      return;
    }

    setFilterBy("");
    setItemType("");
    if (setBrandId) {
      setBrandId(selectedBrandId);
    }
    if (onBrandSelect) {
      onBrandSelect(selectedBrandId, selectedBrandName);
    }

    setSelectedKey("5");
    setIsModalOpen(false);
  };

  const handleOk = () => {
    setIsModalOpen(false);
  };
  const handleCancel = () => {
    setIsModalOpen(false);
  };

  const handleSearch = (value) => {
    clearTimeout(debounceSearch.current);

    debounceSearch.current = setTimeout(() => {
      showAllBrandList(value);
    }, 400);
  };

  // Add a tick icon dynamically to the selected item
  const itemsWithTick = initialItems.map((item) => ({
    ...item,
    label: (
      <Space>
        {item.key === "5" && selectedBrandName ? selectedBrandName : item.label}
        {selectedKey === item.key && <FcCheckmark className="sort_icons" />}
      </Space>
    ),
  }));

  return (
    <>
      <div className="filters">
        <Dropdown
          open={open}
          onOpenChange={(flag) => setOpen(flag)}
          overlayClassName="product-filter-dropdown"
          menu={{
            items: itemsWithTick,
            onClick: handleFilter, // Pass the handler here
          }}
          trigger={["click"]}
          dropdownRender={(menuNode) => (
            <div style={{ background: '#fff' }}>
              {menuNode}
              <Divider style={{ margin: 0 }} />
              <div className="filter-reset">
                <Button
                  size="small"
                  onClick={() => {
                    setItemType("");
                    setFilterBy("");
                    setOpen(false);
                    if (setBrandId && !onBrandSelect) {
                      setBrandId("");
                    }
                    if (!onBrandSelect) {
                      setSelectedKey(null);
                      setSelectedBrandId("");
                      setSelectedBrandName("");
                    }
                  }}
                >
                  Reset
                </Button>
              </div>
            </div>
          )}
        >
          <Button shape="circel" icon={<FilterOutlined />} type="primary">
            {/* <span className="filter_list">Customer Favorites</span> */}
          </Button>
        </Dropdown>
      </div>

      <Modal width={400} title="Select Brand" open={isModalOpen} onOk={handleOk} onCancel={handleCancel} footer={false}>
        {isBrandLoading ? (
          <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '30px 0' }}>
            <Spin size="small" />
          </div>
        ) : (
          <div className="vendor_search_form">
            <Form layout="vertical" form={form} onFinish={submitHandler}>
              <Form.Item name="branchId">
                <Select
                  showSearch
                  placeholder="Select Branch"
                  allowClear
                  onSearch={handleSearch}
                  filterOption={false}
                  options={brandList.map(option => ({
                    value: option.brandID,
                    label: `${option.brandName}`,
                  }))}
                  onChange={(value, option) => {
                    setSelectedBrandId(value);
                    setSelectedBrandName(option?.label || "");
                  }}
                />
              </Form.Item>
              <Form.Item>
                <div className="order_sent_btn">
                  <Button htmlType='submit'>Submit</Button>
                </div>
              </Form.Item>
            </Form>
          </div>
        )}
      </Modal>
    </>
  );
}

export default ProductFilter;
